3	// Live-Daten zum Strommarkt (DE, AT, CH) – nur öffentliche, schlüsselfreie Quellen:
4	//   - Fraunhofer ISE Energy-Charts (CC BY 4.0): Day-Ahead-Preis je Gebotszone
5	//     (DE-LU in 15-Minuten-Auflösung, AT 15 Minuten, CH stündlich) und öffentliche
6	//     Nettostromerzeugung je Quelle und Land. https://api.energy-charts.info
7	//   - aWATTar (Fallback für die Preise): stündlicher Day-Ahead-Preis,
8	//     api.awattar.de (DE) bzw. api.awattar.at (AT). Für die Schweiz gibt es
9	//     keinen schlüsselfreien Fallback – fällt Energy-Charts aus, bleibt die
10	//     Preisreihe leer und die Seite zeigt ihren ehrlichen Fehlzustand.
11	//
12	// Alle Abrufe laufen serverseitig mit Next-Cache (revalidate), damit Besucher
13	// nie direkt die Drittanbieter treffen und die Seite schnell bleibt. Der Cache
14	// ist je Land getrennt, weil die Zone bzw. das Land in der URL steht.
15	
16	const EC = "https://api.energy-charts.info";
17	
18	// Gebotszone (Preis) und Land (Erzeugung) je Länderwahl. Parameter am 11.10.2026
19	// per Probeabruf an der API verifiziert: /price?bzn=AT (96 Viertelstundenwerte,
20	// EUR/MWh), /price?bzn=CH (24 Stundenwerte, EUR/MWh – die Schweizer Auktion
21	// notiert in Euro), /public_power?country=at bzw. =ch liefern u. a. Solar,
22	// Wind onshore, Load und Renewable share of load; CH zusätzlich Nuclear.
23	export const MARKT_ZONEN = {
24	  DE: { bzn: "DE-LU", country: "de", awattar: "https://api.awattar.de/v1/marketdata" },
25	  AT: { bzn: "AT", country: "at", awattar: "https://api.awattar.at/v1/marketdata" },
26	  CH: { bzn: "CH", country: "ch", awattar: null },
27	};
