29	/** "DE" | "AT" | "CH" (alles andere, auch null = gemeinsame Seite, fällt auf DE zurück) */
30	export function marktLand(land) {
31	  const l = typeof land === "string" ? land.toUpperCase() : null;
32	  return MARKT_ZONEN[l] ? l : "DE";
33	}
