35	// Umsatzsteuer & typische Netzentgelte/Umlagen – für die Einordnung
36	// "was kostet eine kWh mit dynamischem Tarif ungefähr". Bewusst als
37	// Orientierung gekennzeichnet. Deutsche Orientierungswerte: nur für DE
38	// verwenden, AT/CH ohne diese Einordnung (bzw. mit LandHinweis).
39	export const TARIF_ANNAHMEN = {
40	  aufschlagCt: 19.5, // Netzentgelt, Abgaben, Umlagen, Marge (netto, ct/kWh) – grobe Orientierung 2026
41	  mwst: 0.19,
42	  festpreisCt: 36, // durchschnittlicher Haushalts-Festpreis in ct/kWh brutto (Orientierung)
43	};
