45	// Abrufschutz (Masterplan S0 Nr. 8): Ein hängender Drittanbieter darf Render-/ISR-Worker von
46	// Startseite, /energie-live und /api/energie/live nicht blockieren. Je Versuch höchstens
47	// TIMEOUT_MS, insgesamt VERSUCHE Versuche mit wachsender Pause; 4xx wird nicht wiederholt.
48	// Schlimmster Fall je Quelle: 2 × 6 s + 0,4 s ≈ 12,4 s, danach greift der Fallback des Aufrufers.
49	const TIMEOUT_MS = 6000;
50	const VERSUCHE = 2;
51	const PAUSE_MS = 400;
52	
53	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
54	
55	async function holeJson(url, revalidate) {
56	  let letzterFehler;
57	  for (let versuch = 1; versuch <= VERSUCHE; versuch++) {
58	    try {
59	      const res = await fetch(url, {
60	        next: { revalidate },
61	        signal: AbortSignal.timeout(TIMEOUT_MS),
62	        headers: { Accept: "application/json", "User-Agent": "oekoinvest energy widget" },
63	      });
64	      if (res.ok) return await res.json();
65	      letzterFehler = new Error(`${url} -> ${res.status}`);
66	      // Client-Fehler (außer 408/429) ändern sich durch Wiederholen nicht
67	      if (res.status < 500 && res.status !== 408 && res.status !== 429) break;
68	    } catch (e) {
69	      letzterFehler = e?.name === "TimeoutError" ? new Error(`${url} -> Timeout nach ${TIMEOUT_MS} ms`) : e;
70	    }
71	    if (versuch < VERSUCHE) await warte(PAUSE_MS * versuch);
72	  }
73	  throw letzterFehler;
74	}
