76	/** Tagesbeginn (lokal Europe/Berlin) als ISO-Datum YYYY-MM-DD */
77	function berlinDatum(offsetTage = 0) {
78	  const d = new Date(Date.now() + offsetTage * 86400000);
79	  return new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(d);
80	}
