82	/**
83	 * Day-Ahead-Preise für heute (und morgen, falls schon veröffentlicht – ab ca. 13 Uhr)
84	 * für die Gebotszone des Landes ("DE" → DE-LU, "AT", "CH").
85	 * Rückgabe: { quelle, zone, aufloesungMin, punkte: [{ t: ms, eurMwh }] }
86	 */
87	export async function getSpotPrices(land = "DE") {
88	  const z = MARKT_ZONEN[marktLand(land)];
89	  try {
90	    const start = berlinDatum(0);
91	    const ende = berlinDatum(2);
92	    const j = await holeJson(`${EC}/price?bzn=${z.bzn}&start=${start}&end=${ende}`, 900);
93	    const punkte = (j.unix_seconds || [])
94	      .map((s, i) => ({ t: s * 1000, eurMwh: j.price?.[i] }))
95	      .filter((p) => typeof p.eurMwh === "number");
96	    if (punkte.length) {
97	      // Auflösung aus den Zeitstempeln: DE-LU/AT 15 Minuten, CH stündlich
98	      const aufloesungMin = punkte.length > 1 ? Math.max(1, Math.round((punkte[1].t - punkte[0].t) / 60000)) : 60;
99	      return { quelle: "Energy-Charts (Fraunhofer ISE)", zone: z.bzn, aufloesungMin, punkte };
100	    }
101	  } catch (e) {
102	    console.error(`energy-charts price ${z.bzn}:`, e.message);
103	  }
104	  if (z.awattar) {
105	    try {
106	      const j = await holeJson(z.awattar, 900);
107	      const punkte = (j.data || []).map((p) => ({ t: p.start_timestamp, eurMwh: p.marketprice }));
108	      return { quelle: "aWATTar", zone: z.bzn, aufloesungMin: 60, punkte };
109	    } catch (e) {
110	      console.error("awattar:", e.message);
111	    }
112	  }
113	  // Kein Fallback (CH) oder beide Quellen gestört: ehrlicher Leerzustand
114	  return { quelle: null, zone: z.bzn, aufloesungMin: 60, punkte: [] };
115	}
