117	/**
118	 * Stromerzeugung nach Quelle (Energy-Charts public_power) ab gestern 0 Uhr bis jetzt
119	 * für das Land ("DE" | "AT" | "CH"). Gestern ist mit dabei, damit Diagramme auch kurz
120	 * nach Mitternacht einen vollständigen 24-Stunden-Verlauf zeigen können. Die
121	 * Kennzahlen im Snapshot nutzen weiterhin den jüngsten Wert (idx).
122	 */
123	export async function getGeneration(land = "DE") {
124	  const z = MARKT_ZONEN[marktLand(land)];
125	  try {
126	    const j = await holeJson(`${EC}/public_power?country=${z.country}&start=${berlinDatum(-1)}&end=${berlinDatum(1)}`, 900);
127	    const zeiten = (j.unix_seconds || []).map((s) => s * 1000);
128	    const reihe = (name) => j.production_types?.find((p) => p.name === name)?.data || [];
129	    const summe = (...namen) =>
130	      zeiten.map((_, i) => namen.reduce((acc, n) => acc + (Number(reihe(n)[i]) || 0), 0));
131	
132	    const serien = {
133	      solar: reihe("Solar"),
134	      windOnshore: reihe("Wind onshore"),
135	      windOffshore: reihe("Wind offshore"),
136	      biomasse: reihe("Biomass"),
137	      wasser: summe("Hydro Run-of-River", "Hydro water reservoir"),
138	      braunkohle: reihe("Fossil brown coal / lignite"),
139	      steinkohle: reihe("Fossil hard coal"),
140	      gas: reihe("Fossil gas"),
141	      kernkraft: reihe("Nuclear"), // nur CH (DE/AT liefern die Reihe nicht)
142	      // Rest der öffentlichen Nettoerzeugung (Müll, Öl, Grubengas, Geothermie, Pumpspeicher, Sonstige)
143	      sonstige: summe("Waste", "Fossil oil", "Fossil coal-derived gas", "Geothermal", "Others", "Hydro pumped storage"),
144	      last: reihe("Load"),
145	      eeAnteil: reihe("Renewable share of load"),
146	    };
147	
148	    // Letzter Zeitpunkt mit Solar- UND Lastwert
149	    let idx = -1;
150	    for (let i = zeiten.length - 1; i >= 0; i--) {
151	      if (serien.solar[i] != null && serien.last[i] != null) { idx = i; break; }
152	    }
153	    return { quelle: "Energy-Charts (Fraunhofer ISE)", land: marktLand(land), zeiten, serien, idx };
154	  } catch (e) {
155	    console.error(`energy-charts power ${z.country}:`, e.message);
156	    return { quelle: null, land: marktLand(land), zeiten: [], serien: {}, idx: -1 };
157	  }
158	}
