160	/** Kompakte Live-Zusammenfassung für Ticker, Widgets und Dashboard – je Land. */
161	export async function getEnergySnapshot(land = "DE") {
162	  const l = marktLand(land);
163	  const [preise, erzeugung] = await Promise.all([getSpotPrices(l), getGeneration(l)]);
164	  const jetzt = Date.now();
165	  const schritt = preise.aufloesungMin * 60000;
166	
167	  const heuteStr = berlinDatum(0);
168	  const tagVon = (t) => new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(new Date(t));
169	  const heute = preise.punkte.filter((p) => tagVon(p.t) === heuteStr);
170	  const morgen = preise.punkte.filter((p) => tagVon(p.t) === berlinDatum(1));
171	  const aktuell = preise.punkte.find((p) => p.t <= jetzt && jetzt < p.t + schritt) || null;
172	
173	  const stat = (arr) => {
174	    if (!arr.length) return null;
175	    const werte = arr.map((p) => p.eurMwh);
176	    const min = arr.reduce((a, b) => (b.eurMwh < a.eurMwh ? b : a));
177	    const max = arr.reduce((a, b) => (b.eurMwh > a.eurMwh ? b : a));
178	    return { avg: werte.reduce((a, b) => a + b, 0) / werte.length, min, max, negativ: werte.filter((w) => w < 0).length };
179	  };
180	
181	  const { serien, idx, zeiten } = erzeugung;
182	  const wert = (s) => (idx >= 0 && serien[s] ? Number(serien[s][idx]) || 0 : null);
183	  const wind = idx >= 0 ? (wert("windOnshore") || 0) + (wert("windOffshore") || 0) : null;
184	
185	  return {
186	    stand: new Date().toISOString(),
187	    land: l,
188	    preis: {
189	      quelle: preise.quelle,
190	      zone: preise.zone,
191	      aufloesungMin: preise.aufloesungMin,
192	      aktuell,
193	      heute: stat(heute),
194	      morgen: stat(morgen),
195	      punkte: preise.punkte,
196	    },
197	    erzeugung: {
198	      quelle: erzeugung.quelle,
199	      zeitpunkt: idx >= 0 ? zeiten[idx] : null,
200	      solarMw: wert("solar"),
201	      windMw: wind,
202	      lastMw: wert("last"),
203	      eeAnteil: wert("eeAnteil"),
204	      solarAnteil: idx >= 0 && wert("last") ? (wert("solar") / wert("last")) * 100 : null,
205	      zeiten,
206	      serien,
207	    },
208	  };
209	}
