211	/** €/MWh (Börse, netto) -> ct/kWh */
212	export const ctKwh = (eurMwh) => eurMwh / 10;
213	
214	/** Grobe Brutto-Endkundenkosten bei dynamischem Tarif in ct/kWh (deutsche Orientierungswerte, nur DE). */
215	export const dynamischBrutto = (eurMwh) => (ctKwh(eurMwh) + TARIF_ANNAHMEN.aufschlagCt) * (1 + TARIF_ANNAHMEN.mwst);
